export default function Migrate() {
  const [logs, setLogs]     = useState([{ msg: "Ready. Tap the button to upload all client data to Firebase.", cls: "info" }]);
  const [running, setRunning] = useState(false);
  const [done, setDone]     = useState(false);

  const addLog = (msg, cls="info") => setLogs(prev => [...prev, { msg, cls }]);

  const run = async () => {
    setRunning(true);
    setLogs([]);
    addLog("Connecting to Firebase...");
    try {
      const ref = doc(_db, "vip", "clients");
      addLog("Clearing old data...");
      await deleteDoc(ref);
      addLog("Old data cleared!", "ok");
      addLog("Uploading " + CLIENTS.length + " clients...");
      await setDoc(ref, { list: CLIENTS });
      addLog("All " + CLIENTS.length + " clients uploaded!", "ok");
      addLog("MIGRATION COMPLETE!", "done");
      addLog("You can now close this page and open the VIP Tracker.", "info");
      setDone(true);
    } catch(e) {
      addLog("Error: " + e.message, "err");
      setRunning(false);
    }
  };

  const colors = { info:"#6ababa", ok:"#4edee4", err:"#ff6b6b", done:"#ffd700" };

  return (
    <div style={{minHeight:"100vh",background:"#0a0f0f",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24,fontFamily:"monospace"}}>
      <img src="/logo.png" alt="SNB" style={{width:90,height:90,objectFit:"contain",marginBottom:16}} />
      <div style={{fontSize:20,fontWeight:900,letterSpacing:3,color:"#4edee4",marginBottom:6}}>SNB MIGRATION TOOL</div>
      <div style={{fontSize:11,color:"#6ababa",letterSpacing:2,marginBottom:8}}>UPDATED CSV DATA · {CLIENTS.length} CLIENTS</div>
      <div style={{fontSize:11,color:"#ff6b6b",letterSpacing:1,marginBottom:24,textAlign:"center",maxWidth:400,lineHeight:1.6}}>
        &#9888; This will completely overwrite all current Firebase data.<br/>Only run this once on a fresh load.
      </div>

      {!done && (
        <button onClick={run} disabled={running} style={{
          background: running ? "#1a3333" : "linear-gradient(135deg,#0cc0df,#4edee4)",
          border:"none",color:running?"#4edee4":"#000",borderRadius:12,
          padding:"14px 32px",cursor:running?"not-allowed":"pointer",
          fontWeight:900,fontSize:14,letterSpacing:2,fontFamily:"monospace",marginBottom:20,
        }}>
          {running ? "UPLOADING..." : "UPLOAD TO FIREBASE"}
        </button>
      )}

      {done && (
        <a href="/" style={{
          background:"linear-gradient(135deg,#0cc0df,#4edee4)",
          color:"#000",borderRadius:12,padding:"14px 32px",
          fontWeight:900,fontSize:14,letterSpacing:2,fontFamily:"monospace",
          marginBottom:20,textDecoration:"none",display:"inline-block",
        }}>OPEN VIP TRACKER &#8594;</a>
      )}

      <div style={{background:"#060f0f",border:"1px solid #1a3333",borderRadius:12,padding:16,width:"100%",maxWidth:500,maxHeight:300,overflowY:"auto"}}>
        {logs.map((l,i)=>(
          <div key={i} style={{color:colors[l.cls]||"#6ababa",fontSize:12,lineHeight:1.8}}>
            {l.cls==="done"?"&#127881; ":l.cls==="ok"?"&#10003; ":l.cls==="err"?"&#10060; ":"&#128062; "}{l.msg}
          </div>
        ))}
      </div>
    </div>
  );
}
